test('re-register backs up an edited file instead of overwriting it', () => {
  const d = tmp();
  const r = register(opts(d, 'dots', { skillsDir: path.join(d, 'skills') }));
  fs.appendFileSync(r.router!, '\nmine\n');
  register(opts(d, 'dots', { skillsDir: path.join(d, 'skills') }));
  const kept = files(path.join(d, 'state', 'backups', 'harness'));
  expect(kept.some(f => f.endsWith('gstack/SKILL.md'))).toBe(true);
});

test('refresh re-registers in place under the same ids', () => {
  const d = tmp();
  const a = register(opts(d, 'dots', { skillsDir: path.join(d, 'skills') }));
  const rs = refresh({ ...opts(d, 'dots'), version: 'next' });
  expect(rs.map(r => r.id)).toEqual([a.id]);
  expect(listLedgers(path.join(d, 'state')).length).toBe(1);
});

test('harness registration requires experimental tier', () => {
  const c = ALL_HOST_CONFIGS.find(h => h.name === 'openclaw')!;
  expect(validateHostConfig({ ...c, tier: 'instruction-only' })).toContain('install.registration harness needs tier experimental (setup registers it through gstack-harness)');
});

